def pipeline_from_config(config):
    """Reconstruct an allowlisted baseline; never import a report-provided name."""
    from timegym.pipeline import Pipeline

    expected = {"schema_version", "model", "window_length", "strategy", "replayable"}
    if not isinstance(config, dict) or set(config) != expected or type(config["schema_version"]) is not int or config["schema_version"] != 1:
        raise ValueError("Unsupported or incomplete pipeline configuration schema")
    if config["replayable"] is not True:
        raise ValueError("This model configuration is not automatically replayable; supply its original model code")
    model = config["model"]
    if not isinstance(model, dict) or set(model) != {"kind", "class", "parameters"} or model["kind"] != "builtin":
        raise ValueError("Replay accepts only allowlisted built-in model descriptions")
    name = model["class"]
    if not isinstance(name, str) or name not in _BUILTINS:
        raise ValueError("Model class is not in the replay allowlist")
    parameters = model["parameters"]
    if not isinstance(parameters, dict) or set(parameters) != _PARAMETERS[name]:
        raise ValueError("Unexpected or missing built-in model constructor parameters")
    window = config["window_length"]
    if isinstance(window, bool) or not isinstance(window, int) or window < 1:
        raise ValueError("window_length must be a positive integer")
    if name == "GaussianAR1Forecaster":
        seed = parameters["seed"]
        if isinstance(seed, bool) or not isinstance(seed, int) or seed < 0:
            raise ValueError("Model seed must be a nonnegative integer for replay")
    return Pipeline(_BUILTINS[name](**parameters), window_length=window, strategy=config["strategy"])

# %% ../notebooks/10_reports_and_replay.ipynb #10_reports_and_repla-28
def runtime_provenance():
    """Package/dependency versions and a content digest of available Python source."""
    from timegym import __version__, __file__ as package_file

    versions = {}
    for name in ("timegym", "numpy", "pandas", "scipy", "scikit-learn"):
        try:
            versions[name] = metadata.version(name)
        except metadata.PackageNotFoundError:
            versions[name] = None
    root = Path(package_file).resolve().parent
    digest = hashlib.sha256()
    paths = sorted(root.rglob("*.py"))
    for path in paths:
        digest.update(path.relative_to(root).as_posix().encode("utf-8") + b"\0")
        digest.update(path.read_bytes() + b"\0")
    return {"timegym_version": __version__, "python": platform.python_version(),
            "python_implementation": platform.python_implementation(), "dependencies": versions,
            "source": {"algorithm": "sha256", "scope": "timegym/**/*.py relative paths and contents",
                       "digest": digest.hexdigest(), "file_count": len(paths)}}

# %% ../notebooks/10_reports_and_replay.ipynb #10_reports_and_repla-30
def diagnostic_settings(*, check_dependence=False, n_calibration=99, alpha=0.05, dependence_seed_offset=100_000):
    """Validate all settings that influence Pipeline.test evaluation."""
    if not isinstance(check_dependence, bool):
        raise ValueError("check_dependence must be a boolean")
    if isinstance(n_calibration, bool) or not isinstance(n_calibration, int) or n_calibration < 1:
        raise ValueError("n_calibration must be a positive integer")
    if isinstance(dependence_seed_offset, bool) or not isinstance(dependence_seed_offset, int) or dependence_seed_offset < 0:
        raise ValueError("dependence_seed_offset must be a nonnegative integer")
    if isinstance(alpha, bool) or not isinstance(alpha, (int, float)) or not np.isfinite(alpha) or not 0 < alpha < 1:
        raise ValueError("alpha must be finite and in (0, 1)")
    return {"check_dependence": check_dependence, "n_calibration": n_calibration,
            "alpha": float(alpha), "dependence_seed_offset": dependence_seed_offset}

# %% ../notebooks/10_reports_and_replay.ipynb #10_reports_and_repla-32
def replay_case(report, case_index=0):
    """Replay one report case and compare regenerated metrics and diagnostics.

    The return value is a new TestReport. ``metadata['replay']`` records exact
    result equality and source/dependency agreement. Replaying in a different
    environment is allowed and reported, not silently called identical.
    """
    from timegym.scenarios import Scenario

    payload = report.to_dict() if hasattr(report, "to_dict") else report
    if not isinstance(payload, dict) or payload.get("schema_version") != "2.0":
        raise ValueError("Replay requires a TimeGym report with schema_version '2.0'")
    if isinstance(case_index, bool) or not isinstance(case_index, int) or case_index < 0:
        raise ValueError("case_index must be a nonnegative integer")
    cases = payload.get("cases")
    if not isinstance(cases, list) or case_index >= len(cases):
        raise ValueError("case_index is outside the saved report")
    original = cases[case_index]
    saved_metadata = payload.get("metadata", {})
    if not isinstance(original, dict) or not isinstance(saved_metadata, dict):
        raise ValueError("Report case and metadata must be JSON objects")
    pipeline = pipeline_from_config(saved_metadata.get("pipeline_config"))
    settings = saved_metadata.get("diagnostic_settings")
    setting_keys = {"check_dependence", "n_calibration", "alpha", "dependence_seed_offset"}
    if not isinstance(settings, dict) or set(settings) != setting_keys:
        raise ValueError("Report diagnostic settings are absent or unsupported")
    settings = diagnostic_settings(**settings)
    manifest = original.get("manifest", {})
    if not isinstance(manifest, dict):
        raise ValueError("Scenario manifest must be a JSON object")
    if type(manifest.get("schema_version")) is not int or manifest["schema_version"] != 1:
        raise ValueError("Unsupported scenario manifest schema")
    constructor_keys = ("kind", "context_length", "horizon", "parameters", "n_targets", "seed")
    if any(key not in manifest for key in constructor_keys):
        raise ValueError("Scenario manifest lacks required reconstruction fields")
    if original.get("seed") != manifest["seed"] or original.get("scenario") != manifest["kind"]:
        raise ValueError("Case identity and scenario manifest disagree")
    scenario = Scenario(**{key: manifest[key] for key in constructor_keys})
    regenerated = pipeline.test([scenario], seeds=[manifest["seed"]], **settings)
    actual = regenerated.cases[0].to_dict()
    regenerated.metadata["replay"] = {
        "case_index": case_index,
        "metrics_match": actual["metrics"] == original.get("metrics"),
        "diagnostics_match": actual["diagnostics"] == original.get("diagnostics"),
        "manifest_match": actual["manifest"] == manifest,
        "source_matches": regenerated.metadata["source"] == saved_metadata.get("source"),
        "dependencies_match": regenerated.metadata["dependencies"] == saved_metadata.get("dependencies"),
        "python_matches": regenerated.metadata["python"] == saved_metadata.get("python"),
    }
    return regenerated
